pub fn subscribe<T, Event>(
    &mut self,
    entity: &Entity<T>,
    on_event: impl FnMut(Entity<T>, &Event, &mut App) + 'static,
) -> Subscription
where
    T: 'static + EventEmitter<Event>,
    Event: 'static,
{
    let app = self.app();
    let mut lock = app.borrow_mut();
    lock.subscribe(entity, on_event)
}

